#include <iostream>

// Function prototypes with explicit parameter types
void modifyByValue(int val);
void modifyByPointer(int* ptr); // C-style simulated reference
void modifyByReference(int& ref); // Modern C++ reference

int main() {
    int a = 10;
    int b = 20;
    int c = 30;

    std::cout << "Initial values: a=" << a << " b=" << b << " c=" << c << "\n";

    modifyByValue(a);       // Pass-by-value: copy made
    modifyByPointer(&b);    // C-style pass-by-reference using address-of
    modifyByReference(c);  // C++ pass-by-reference

    std::cout << "After calls:    a=" << a << " b=" << b << " c=" << c << "\n";
    return 0;
}

void modifyByValue(int val) {
    val += 100; // Modifies only the stack frame copy
}

void modifyByPointer(int* ptr) {
    *ptr += 100; // Modifies caller variable via dereference
}

void modifyByReference(int& ref) {
    ref += 100; // Direct modification via C++ reference
}

#include <iostream>

// Traditional unscoped enum starting at 0, auto-incrementing
enum Status { CONTINUE, WON, LOST };

// Enum with custom explicit values
enum DiceParam {
    SHIFT = 1,
    SCALE = 6
};

// Evaluates outcome and demonstrates scaling and shifting formula: n = a + raw % b
Status evaluateRoll(int rawValue, int& rollResult) {
    rollResult = SHIFT + (rawValue % SCALE);
    if (rollResult == 7 || rollResult == 11) {
        return WON;
    } else if (rollResult == 2 || rollResult == 3 || rollResult == 12) {
        return LOST;
    }
    return CONTINUE;
}

int main() {
    int rawValues[] = {5, 6, 1};
    for (int raw : rawValues) {
        int roll = 0;
        Status s = evaluateRoll(raw, roll);
        std::cout << "Raw: " << raw 
                  << " -> Rolled: " << roll 
                  << ", Status: " << s << "\n";
    }
    return 0;
}

#include <iostream>

// File scope variable (static storage duration, auto-initialized to 0 if omitted)
int globalCount = 100;

// Function prototype: parameter name 'val' has function-prototype scope
void demonstrateStorage(int val);

int main() {
    // Block scope variable
    int val = 5;
    std::cout << "main block val: " << val << "\n";

    demonstrateStorage(val);
    demonstrateStorage(val);

    // Nested block demonstrating shadowing
    {
        int val = 999; // Shadows outer val
        std::cout << "Nested inner val: " << val << "\n";
    }

    std::cout << "Restored outer val: " << val << "\n";
    return 0;
}

void demonstrateStorage(int val) {
    // Local static variable: initialized once, persists between calls
    static int callCount = 0;
    callCount++;
    std::cout << "demonstrateStorage callCount: " << callCount 
              << ", received val: " << val << "\n";
}

#include <iostream>

// Recursive factorial
unsigned long long factorial(unsigned int n) {
    // Base case: 0! = 1, 1! = 1
    if (n <= 1) {
        return 1;
    }
    // Recursive step: n * (n - 1)!
    return n * factorial(n - 1);
}

// Iterative factorial
unsigned long long factorialIterative(unsigned int n) {
    unsigned long long result = 1;
    for (unsigned int i = 2; i <= n; ++i) {
        result *= i;
    }
    return result;
}

int main() {
    unsigned int n = 5;

    // && guarantees left operand is evaluated first (short-circuit logic)
    bool isValid = (n > 0) && (factorial(n) == factorialIterative(n));

    // Ternary operator ?: guarantees evaluation of condition first
    std::cout << "Factorial of " << n << " = " << factorial(n) << "\n";
    std::cout << "Validation: " << (isValid ? "MATCH" : "MISMATCH") << "\n";
    return 0;
}
